window.__finlexDocLoaded(10203,{"id":10203,"articles":[{"id":1000843,"no":"Overview","heading":"Scope & Core Objective (Public Summary)","text":"Establishes cost determination (FIFO, Weighted Average, Specific Identification, and LIFO) and subsequent measurement of inventory at Lower of Cost and Net Realizable Value (LCNRV) or Lower of Cost or Market (LCM for LIFO/retail).","seq":0},{"id":1000844,"no":"ASC 330-10","heading":"LIFO Costing, LCNRV vs. LCM & Prohibition of Reversals","text":"• Cost Formulas (ASC 330-10-30-9): FIFO, Average Cost, Specific Identification, AND Last-In, First-Out (LIFO) are all permitted (subject to IRS LIFO conformity rule if used for US tax).\n• Subsequent Measurement (ASC 330-10-35): FIFO & Average Cost inventory is measured at Lower of Cost and NRV (LCNRV); LIFO and Retail Inventory Method remain measured at Lower of Cost or Market (replacement cost bounded by NRV ceiling and NRV-less-normal-profit floor).\n• Write-Down Reversals (ASC 330-10-35-14): Once inventory is written down below cost, the reduced amount establishes a NEW cost basis — reversals in subsequent periods are STRICTLY PROHIBITED.","seq":1},{"id":1000845,"no":"US GAAP vs. IFRS / CAS","heading":"Key Cross-Framework Differences","text":"• Two Iconic US GAAP vs. IFRS/CAS Divergences: (1) LIFO is PERMITTED under ASC 330 but PROHIBITED under IAS 2.25 and CAS 1; (2) Reversal of prior inventory write-downs is PROHIBITED under ASC 330 but REQUIRED (up to original cost) under IAS 2.33 and CAS 1.","seq":2},{"id":1000846,"no":"Official Access","heading":"Official FASB Codification & Reference Entry","text":"Official Portal (FASB Accounting Standards Codification®): https://asc.fasb.org/\nStatus: in_force (FASB ASC free Basic View available at https://asc.fasb.org/).","seq":3}]});
